CREATE VIEW sales AS SELECT i.item_id,o.order_id,o.customer_id,o.day,substr(CAST(o.day AS TEXT),1,7) AS month, substr(CAST(o.day AS TEXT),1,4) AS year,o.channel,s.region,p.category_id,c.category,i.product_id,i.quantity,COALESCE(r.qty,0) AS returned,pr.discount,i.quantity*i.unit_price AS gross,ROUND((i.quantity-COALESCE(r.qty,0))*i.unit_price*(1-pr.discount)+0.000000001,2) AS net,ROUND((i.quantity-COALESCE(r.qty,0))*i.unit_cost,2) AS cogs FROM order_items i JOIN orders o ON i.order_id=o.order_id JOIN products p ON i.product_id=p.product_id JOIN categories c ON p.category_id=c.category_id JOIN promotions pr ON i.promotion_id=pr.promotion_id JOIN stores s ON o.store_id=s.store_id LEFT JOIN (SELECT item_id,SUM(quantity) qty FROM returns GROUP BY item_id) r ON i.item_id=r.item_id WHERE o.status='completed';